'use strict';
/* Profit math — JS port of backend/profit.py (the Python file is the reference).
 * Keep both in lockstep; backend/scripts/parity_check.cjs verifies the port
 * over fixtures generated by scripts/gen_fixtures.py.
 *
 * UMD-ish: browser -> window.OSRSProfit, node -> module.exports.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.OSRSProfit = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  // mirrors backend/config.py
  const GE_TAX_RATE = 0.02;
  const GE_TAX_EXEMPT_BELOW = 50;  // items selling at < this many gp are tax-exempt
  const GE_TAX_CAP = 5_000_000;    // per-item cap

  function geTax(sellPrice) {
    if (sellPrice == null || sellPrice < GE_TAX_EXEMPT_BELOW) return 0;
    return Math.min(Math.floor(sellPrice * GE_TAX_RATE), GE_TAX_CAP);
  }

  // Python round() — banker's rounding. Math.round differs on exact .5
  // (always up); this matches CPython's round-half-to-even.
  function pyRound(x) {
    const f = Math.floor(x);
    const diff = x - f;
    if (diff > 0.5) return f + 1;
    if (diff < 0.5) return f;
    return f % 2 === 0 ? f : f + 1;
  }

  // price_resolved: store.resolve() output. Returns [value, stale, source, vol, volSrc].
  function side(pr, mode, kind) {
    const buy = kind === 'buy';
    const conservative = mode === 'conservative';
    const sideKey = buy === conservative ? 'high' : 'low';
    const volKey = buy === conservative ? 'high_vol' : 'low_vol';
    const [value, stale, source] = pr[sideKey];
    const [v, vsrc] = pr[volKey];
    return [value, stale, source, v, vsrc];
  }

  /* Compute one recipe row. Returns null if any needed price is missing.
   * recipe: {id, skill, level, members, product: {id, qty},
   *          materials: [{id, qty}], fee, note}  (the baked site data shape)
   * itemMap: {item_id: {name, image, limit, value}}
   * store:   OSRSPriceStore instance (resolve(itemId) -> per-side arrays or null)
   */
  function evaluateRecipe(recipe, itemMap, store, mode = 'conservative', craftCosts = null) {
    const prodInfo = itemMap[recipe.product.id];
    if (!prodInfo) return null;
    const prodRes = store.resolve(recipe.product.id);
    if (!prodRes) return null;

    const [sellPrice, sellStale, sellSrc, sellVol] = side(prodRes, mode, 'sell');
    if (sellPrice == null) return null;
    const [prodBuy, prodBuyStale, prodBuySrc, prodBuyVol] = side(prodRes, mode, 'buy');

    const materials = [];
    let cost = recipe.fee || 0;
    let minMatVol = null;
    for (const m of recipe.materials) {
      const info = itemMap[m.id];
      if (!info) return null;
      const res = store.resolve(m.id);
      if (!res) return null;
      const [buyPrice, buyStale, buySrc, buyVol] = side(res, mode, 'buy');
      const [matSell] = side(res, mode, 'sell');
      if (buyPrice == null) return null;
      const craftUnit = craftCosts && (m.id in craftCosts) ? pyRound(craftCosts[m.id]) : null;
      // cheapest acquisition for this material: buy at GE price, or craft it if that is cheaper
      const chosen = craftUnit !== null && craftUnit < buyPrice ? craftUnit : buyPrice;
      materials.push({
        id: m.id,
        name: info.name,
        image_url: info.image,
        qty: m.qty,
        price: buyPrice,
        stale: buyStale,
        source: buySrc,
        vol: buyVol,
        sell: matSell,
        sell_tax: matSell == null ? 0 : geTax(matSell),
        craft: craftUnit,
      });
      cost += chosen * m.qty;
      // how many crafts per 5m does this material's buy-side volume support?
      const supported = m.qty > 0 ? buyVol / m.qty : Infinity;
      minMatVol = minMatVol === null ? supported : Math.min(minMatVol, supported);
    }

    const gross = sellPrice * recipe.product.qty;
    const taxTotal = geTax(sellPrice) * recipe.product.qty;
    const net = gross - taxTotal - cost;
    const netPct = cost > 0 ? pyRound(((net / cost) * 100) * 10) / 10 : null;

    // 4h buy-limit cap: limited by every material and the product itself
    let maxCrafts = null;
    let limited = false;
    for (const m of recipe.materials) {
      const limit = itemMap[m.id].limit;
      if (limit == null) { limited = true; continue; }
      const c = Math.floor(limit / m.qty);
      maxCrafts = maxCrafts === null ? c : Math.min(maxCrafts, c);
    }
    const prodLimit = prodInfo.limit;
    if (prodLimit == null) {
      limited = true;
    } else {
      const c = Math.floor(prodLimit / recipe.product.qty);
      maxCrafts = maxCrafts === null ? c : Math.min(maxCrafts, c);
    }
    if (maxCrafts === null) maxCrafts = 0;
    const net4h = (limited || maxCrafts === 0) ? null : net * maxCrafts;

    const volume = minMatVol !== null ? Math.trunc(Math.min(sellVol, minMatVol)) : Math.trunc(sellVol);

    const toolsOut = [];
    for (const t of recipe.tools || []) {
      const entry = { id: t.id ?? null, name: t.name, image_url: null,
                      buy: null, buy_vol: 0, sell: null, tax: 0 };
      if (entry.id && itemMap[entry.id]) {
        const info = itemMap[entry.id];
        entry.image_url = info.image;
        const res = store.resolve(entry.id);
        if (res) {
          entry.buy = res.high[0];
          entry.buy_vol = res.high_vol[0];
          entry.sell = res.low[0];
          entry.tax = res.low[0] == null ? 0 : geTax(res.low[0]);
        }
      }
      toolsOut.push(entry);
    }

    return {
      recipe_id: recipe.id,
      skill: recipe.skill,
      level: recipe.level,
      extra_skills: recipe.extra_skills || [],
      xp: recipe.xp != null ? recipe.xp : 0,
      members: recipe.members,
      product: {
        id: recipe.product.id,
        name: prodInfo.name,
        image_url: prodInfo.image,
        qty: recipe.product.qty,
        price: sellPrice,
        buy: prodBuy,
        buy_vol: prodBuyVol,
        value: prodInfo.value ?? null,
        stale: sellStale,
        source: sellSrc,
        vol: sellVol,
      },
      materials,
      fee: recipe.fee || 0,
      cost: pyRound(cost),
      gross,
      tax: taxTotal,
      net: pyRound(net),
      net_pct: netPct,
      volume: Math.max(volume, 0),
      max_crafts_4h: maxCrafts,
      net_4h: net4h === null ? null : pyRound(net4h),
      mode,
      note: recipe.note ?? null,
      tools: toolsOut,
      facilities: recipe.facilities || [],
    };
  }

  /* Evaluate every recipe (the old /api/recipes route logic, minus filters).
   * Two passes: pass 1 computes per-unit craft costs for every product that is
   * also used as a material elsewhere; pass 2 evaluates all recipes with those
   * costs available. Returns {rows, skippedNoPrice}. */
  function evaluateAll(recipes, itemMap, store, mode = 'conservative') {
    const materialIds = new Set();
    for (const r of recipes) for (const m of r.materials) materialIds.add(m.id);
    const craftCosts = {};
    for (const r of recipes) {
      if (!materialIds.has(r.product.id)) continue;
      const row = evaluateRecipe(r, itemMap, store, mode);
      if (!row || row.product.qty < 1) continue;
      const perUnit = row.cost / row.product.qty;
      const pid = r.product.id;
      if (!(pid in craftCosts) || perUnit < craftCosts[pid]) craftCosts[pid] = perUnit;
    }
    const rows = [];
    let skippedNoPrice = 0;
    for (const r of recipes) {
      const row = evaluateRecipe(r, itemMap, store, mode, craftCosts);
      if (!row) { skippedNoPrice++; continue; }
      rows.push(row);
    }
    return { rows, skippedNoPrice };
  }

  return { geTax, pyRound, evaluateRecipe, evaluateAll };
});
